39. #[derive(Debug, Clone, Copy, PartialEq, Eq)]
40. pub enum MenuAction {
41.     NewGame,
42.     LoadGame,
43.     Options,
44.     Quit,
45. }
46. 
47. impl MenuAction {
48.     pub const fn from_cursor(cursor: usize) -> Self {
49.         match cursor % MENU_ACTION_COUNT {
50.             0 => Self::NewGame,
51.             1 => Self::LoadGame,
52.             2 => Self::Options,
53.             _ => Self::Quit,
54.         }
55.     }
56. 
57.     fn label(self) -> &'static str {
58.         match self {
59.             Self::NewGame => "New Game",
60.             Self::LoadGame => "Load Game",
61.             Self::Options => "Options",
62.             Self::Quit => "Quit",
63.         }
64.     }
65. }
