67. #[derive(Debug, Clone, Copy, PartialEq, Eq)]
68. struct SplashLayout {
69.     frame: Rect,
70.     title: Rect,
71.     menu: Rect,
72.     footer: Rect,
73. }
74. 
75. pub const fn menu_action_count() -> usize {
