113. fn build_title_lines(area_width: u16, palette: SplashPalette) -> Vec<Line<'static>> {
114.     if area_width >= WIDE_TITLE_WIDTH {
115.         let colors = gradient(
116.             palette.title_primary,
117.             palette.title_secondary,
118.             TITLE_LINES_WIDE.len(),
119.         );
120.         let mut lines = TITLE_LINES_WIDE
121.             .iter()
122.             .enumerate()
123.             .map(|(index, line)| {
124.                 Line::from(Span::styled(
125.                     (*line).to_string(),
126.                     Style::default()
127.                         .fg(colors[index])
128.                         .add_modifier(Modifier::BOLD),
129.                 ))
130.             })
131.             .collect::<Vec<_>>();
132.         lines.push(Line::from(""));
133.         lines.push(Line::from(Span::styled(
134.             TAGLINE,
135.             Style::default()
136.                 .fg(palette.accent)
137.                 .add_modifier(Modifier::BOLD),
138.         )));
139.         lines
140.     } else {
141.         vec![
142.             Line::from(Span::styled(
143.                 "FARSPACE",
144.                 Style::default()
145.                     .fg(palette.title_primary)
146.                     .add_modifier(Modifier::BOLD),
147.             )),
148.             Line::from(""),
149.             Line::from(Span::styled(
150.                 TAGLINE,
151.                 Style::default()
152.                     .fg(palette.accent)
153.                     .add_modifier(Modifier::BOLD),
154.             )),
155.         ]
156.     }
157. }
