190. fn render_gradient_frame(frame: &mut Frame, area: Rect, palette: SplashPalette) {
191.     if area.width < 2 || area.height < 2 {
192.         return;
193.     }
194. 
195.     let edge = gradient(palette.border_cold, palette.border_hot, area.width as usize);
196.     let buffer = frame.buffer_mut();
197. 
198.     for x in 0..area.width {
199.         let top_glyph = match x {
200.             0 => '╭',
201.             value if value == area.width.saturating_sub(1) => '╮',
202.             _ => '─',
203.         };
204.         let bottom_glyph = match x {
205.             0 => '╰',
206.             value if value == area.width.saturating_sub(1) => '╯',
207.             _ => '─',
208.         };
209.         let top_style = Style::default()
210.             .fg(edge[x as usize])
211.             .bg(palette.void_bg)
212.             .add_modifier(Modifier::BOLD);
213.         let bottom_style = Style::default()
214.             .fg(edge[area.width.saturating_sub(1) as usize - x as usize])
215.             .bg(palette.void_bg)
216.             .add_modifier(Modifier::BOLD);
217. 
218.         if let Some(cell) = buffer.cell_mut((area.x + x, area.y)) {
219.             cell.set_char(top_glyph);
220.             cell.set_style(top_style);
221.         }
222.         if let Some(cell) = buffer.cell_mut((area.x + x, area.bottom().saturating_sub(1))) {
223.             cell.set_char(bottom_glyph);
224.             cell.set_style(bottom_style);
225.         }
226.     }
227. 
228.     for y in 1..area.height.saturating_sub(1) {
229.         let color = lerp_rgb(
230.             palette.border_cold,
231.             palette.border_hot,
232.             y as f32 / area.height.saturating_sub(1) as f32,
233.         );
234.         let style = Style::default()
235.             .fg(color)
236.             .bg(palette.void_bg)
237.             .add_modifier(Modifier::BOLD);
238. 
239.         if let Some(cell) = buffer.cell_mut((area.x, area.y + y)) {
240.             cell.set_char('│');
241.             cell.set_style(style);
242.         }
243.         if let Some(cell) = buffer.cell_mut((area.right().saturating_sub(1), area.y + y)) {
244.             cell.set_char('│');
245.             cell.set_style(style);
246.         }
247.     }
248. }
