250. fn render_menu_starfield(
251.     frame: &mut Frame,
252.     area: Rect,
253.     app_state: &AppState,
254.     palette: SplashPalette,
255. ) {
256.     if area.width == 0 || area.height == 0 {
257.         return;
258.     }
259. 
260.     let mut canvas = Canvas::new(area.width, area.height);
261.     let detail = starfield_detail(area);
262.     let frame_group = if app_state.reduced_motion {
263.         0
264.     } else {
265.         app_state.tick_count / 10
266.     };
267. 
268.     for y in 0..area.height {
269.         for x in 0..area.width {
270.             let base_hash = visual_hash(0, x, y, 0, MENU_STARFIELD_SALT);
271.             let drift_hash = visual_hash(0, x, y, frame_group, MENU_STARFIELD_SALT ^ 0xA5);
272.             let drift = (drift_hash % 100) as f32 / 100.0;
273.             let depth = (base_hash % 100) as f32 / 100.0;
274.             let bg_color = lerp_rgb(
275.                 lerp_rgb(palette.void_bg, palette.nebula_a, depth * 0.12),
276.                 palette.nebula_b,
277.                 drift * 0.05,
278.             );
279. 
280.             let mut symbol = ' ';
281.             let mut style = Style::default().bg(bg_color);
282.             let haze = base_hash % 521;
283. 
284.             if haze == 0 {
285.                 symbol = '░';
286.                 style = style.fg(lerp_rgb(palette.nebula_b, palette.title_secondary, 0.08));
287.             } else if haze == 1 {
288.                 symbol = '·';
289.                 style = style.fg(lerp_rgb(palette.nebula_a, palette.text_muted, 0.14));
290.             }
291. 
292.             if should_render_star(base_hash, detail) && base_hash.is_multiple_of(9) {
293.                 let twinkle_hash = visual_hash(
294.                     0,
295.                     x,
296.                     y,
297.                     frame_group,
298.                     MENU_STARFIELD_SALT ^ MENU_STARFIELD_TWINKLE_SALT_XOR,
299.                 );
300.                 symbol = if twinkle_hash.is_multiple_of(9) {
301.                     '✦'
302.                 } else {
303.                     detail_star_glyph(base_hash, detail)
304.                 };
305.                 let sparkle = 0.5 + (twinkle_hash % 20) as f32 / 100.0;
306.                 style = Style::default().bg(bg_color).fg(lerp_rgb(
307.                     palette.title_primary,
308.                     palette.star_core,
309.                     sparkle,
310.                 ));
311.             }
312. 
313.             canvas.set_cell(x, y, symbol, style, 0);
314.         }
315.     }
316. 
317.     canvas.render_to_buffer(area, frame.buffer_mut());
318. }
