461. /// Render the main menu
462. pub fn render_menu(frame: &mut Frame, area: Rect, app_state: &AppState) {
463.     let (_header_area, main_area, _footer_area) = compose_layout(area);
464.     let palette = Theme::splash_palette();
465. 
466.     render_menu_starfield(frame, main_area, app_state, palette);
467. 
468.     if main_area.width < MIN_SPLASH_WIDTH || main_area.height < MIN_SPLASH_HEIGHT {
469.         render_compact_menu(frame, main_area, app_state, palette);
470.     } else {
471.         render_dashboard(frame, main_area, app_state, palette);
472.     }
473. }
