 pub fn render_footer(frame: &mut Frame, area: Rect, screen: &Screen, context: Option<&str>) {
     let hints = match screen {
         Screen::Menu => vec![
             ("[Enter]", "Start"),
             ("[N]", "New Game"),
             ("[L]", "Load"),
             ("[O]", "Options"),
             ("[Tab/V]", "Cycle Theme"),
             ("[Q]", "Quit"),
         ],
         Screen::EmpireSelect => vec![
