241. struct AppConfig {
242.     visual_mode: VisualMode,
243.     update_channel: UpdateChannel,
244.     auto_update: bool,
245. }
246. 
247. impl Default for AppConfig {
248.     fn default() -> Self {
249.         Self {
250.             visual_mode: VisualMode::default(),
251.             update_channel: UpdateChannel::default(),
252.             auto_update: true,
253.         }
254.     }
255. }
256. 
257. impl App {
258.     fn load_config_from_path(path: &std::path::Path) -> AppConfig {
259.         let Ok(contents) = std::fs::read_to_string(path) else {
260.             return AppConfig::default();
261.         };
262.         let mut cfg = AppConfig::default();
263.         for line in contents.lines() {
264.             let mut parts = line.splitn(2, '=');
265.             let Some(key) = parts.next().map(str::trim) else {
266.                 continue;
267.             };
268.             let Some(val) = parts.next().map(str::trim) else {
269.                 continue;
270.             };
271.             match key {
272.                 "visual_mode" => {
273.                     if let Some(m) = VisualMode::from_config_value(val) {
274.                         cfg.visual_mode = m;
275.                     }
276.                 }
277.                 "update_channel" => {
278.                     if let Some(c) = UpdateChannel::from_config_value(val) {
279.                         cfg.update_channel = c;
280.                     }
281.                 }
282.                 "auto_update" => {
283.                     let v = val.trim().to_ascii_lowercase();
284.                     cfg.auto_update = v != "false" && v != "0" && v != "off";
285.                 }
286.                 _ => {}
287.             }
288.         }
289.         cfg
290.     }
291. 
292.     fn persist_config_to_path(path: &std::path::Path, state: &AppState) -> std::io::Result<()> {
293.         if let Some(parent) = path.parent() {
294.             std::fs::create_dir_all(parent)?;
295.         }
296.         let auto_update_str = if state.auto_update { "true" } else { "false" };
297.         std::fs::write(
298.             path,
299.             format!(
300.                 "visual_mode={}\nupdate_channel={}\nauto_update={}\n",
301.                 state.visual_mode.config_value(),
302.                 state.update_channel.config_value(),
303.                 auto_update_str,
