380.     /// Returns the update channel the user has configured, for use by the binary crate.
381.     pub fn update_channel(&self) -> UpdateChannel {
382.         self.state.update_channel
383.     }
384. 
385.     /// Wire in the update channels from the binary crate's update system.
386.     pub fn set_update_channels(
387.         &mut self,
388.         check_rx: std::sync::mpsc::Receiver<Result<Option<UpdateInfo>, String>>,
389.         download_tx: std::sync::mpsc::SyncSender<UpdateInfo>,
390.         download_rx: std::sync::mpsc::Receiver<Result<String, String>>,
391.     ) {
392.         self.check_rx = Some(check_rx);
393.         self.download_tx = Some(download_tx);
394.         self.download_rx = Some(download_rx);
395.         self.state.update_state = UpdateState::Checking;
396.     }
397. 
398.     /// Start a new game with the given seed (default setup, 1 AI empire).
399.     pub fn new_game(&mut self, seed: u64) {
400.         let setup = ScenarioSetup::default_for_seed(seed);
401.         self.new_game_from_setup(setup);
402.     }
403. 
404.     /// Start a new game from a `ScenarioSetup`.  Logs an error if the setup is invalid.
405.     pub fn new_game_from_setup(&mut self, setup: ScenarioSetup) {
406.         if let Err(e) = setup.validate() {
407.             self.state.log.push(format!("Error: Invalid setup: {}", e));
408.             return;
409.         }
410.         let engine = Engine::new_from_setup(setup);
411. 
412.         // Select the first sector and first star by default
413.         self.state.navigation.selected_sector = engine.state.sectors.keys().next().copied();
414.         self.state.navigation.selected_star = engine.state.stars.keys().next().copied();
415.         self.state.navigation.selected_planet_index = 0;
416. 
417.         // Add initial log entry with setup summary and playability hints
418.         let scenario_summary = if let Some(s) = &engine.state.scenario {
419.             let player_faction = engine
420.                 .state
421.                 .empires
422.                 .get(&engine.state.player_empire)
423.                 .and_then(|empire| empire.empire_def)
424.                 .and_then(empire_definition_by_id)
425.                 .map(|def| def.name)
426.                 .unwrap_or("Unaligned");
427.             format!(
428.                 "Game started — {} galaxy, {} AI empire(s), seed {}, faction {}",
429.                 s.galaxy_size.label(),
430.                 s.ai_empire_count,
431.                 s.seed,
432.                 player_faction,
433.             )
434.         } else {
435.             "Game started".to_string()
436.         };
437.         self.state.log.push(scenario_summary);
438.         self.state.log.push(
439.             "What to do next: Enter Sector Map, scout (S), survey (System:S), then colonize (C)."
440.                 .to_string(),
441.         );
442.         self.state.status_message = Some(
443.             "First turn: Enter sector map, scout systems, choose research, queue a build."
444.                 .to_string(),
445.         );
446. 
447.         self.engine = Some(engine);
448.         self.state.active = Screen::SectorOverview;
449.     }
450. 
451.     /// Save the current game to the given path. Returns an error message on failure.
452.     pub fn save_game(&mut self, path: &std::path::Path) -> Result<(), String> {
453.         let engine = self
454.             .engine
455.             .as_ref()
456.             .ok_or_else(|| "No game in progress".to_string())?;
457.         game_save::save_to_file(&engine.state, path)
458.             .map_err(|e| format!("Error: Save failed ({}): {}", path.display(), e))?;
459.         Ok(())
460.     }
461. 
462.     /// Load a game from the given path. Returns an error message on failure.
463.     pub fn load_game(&mut self, path: &std::path::Path) -> Result<(), String> {
464.         let state = game_save::load_from_file(path)
465.             .map_err(|e| format!("Error: Load failed ({}): {}", path.display(), e))?;
466.         let selected_star = state.stars.keys().next().copied();
467.         let selected_sector = state.sectors.keys().next().copied();
468.         self.engine = Some(Engine::from_state(state));
469.         self.state.navigation.selected_sector = selected_sector;
470.         self.state.navigation.selected_star = selected_star;
471.         self.state.navigation.selected_planet_index = 0;
472.         self.state.active = Screen::SectorOverview;
473.         Ok(())
474.     }
475. 
476.     /// Parse and execute palette input (e.g. "save", ":save").
477.     fn execute_palette_input(&mut self, input: &str) {
478.         let command = match PaletteCommand::parse(input) {
479.             Ok(Some(command)) => command,
480.             Ok(None) => return,
481.             Err(err) => {
482.                 self.push_error_status(format!("Error: Unknown command: {}", err.command()));
483.                 return;
484.             }
485.         };
486.         self.execute_palette_command(command);
487.     }
488. 
489.     fn execute_palette_command(&mut self, cmd: PaletteCommand) {
490.         let path = std::path::PathBuf::from(DEFAULT_SAVE_PATH);
491.         self.execute_palette_command_with_path(cmd, &path);
492.     }
493. 
494.     fn execute_palette_command_with_path(&mut self, cmd: PaletteCommand, path: &Path) {
495.         match cmd {
496.             PaletteCommand::Save => match self.save_game(path) {
497.                 Ok(()) => {
498.                     let msg = format!("Save: wrote {}", path.display());
499.                     self.push_status(LogEntryKind::SaveLoad, msg);
500.                 }
501.                 Err(e) => {
502.                     self.push_error_status(e);
503.                 }
504.             },
505.             PaletteCommand::Load => match self.load_game(path) {
506.                 Ok(()) => {
507.                     let msg = format!("Load: loaded {}", path.display());
508.                     self.push_status(LogEntryKind::SaveLoad, msg);
509.                 }
510.                 Err(e) => {
511.                     self.push_error_status(e);
512.                 }
513.             },
514.             PaletteCommand::ClearRally => {
515.                 self.clear_rally_point();
516.             }
517.             PaletteCommand::VisualMode => {
518.                 self.cycle_visual_mode_with_path(Some(path));
519.             }
520.             PaletteCommand::Dispatch | PaletteCommand::News => {
521.                 self.open_latest_dispatch();
522.             }
523.         }
524.     }
525. 
