680.                         !self.state.overlay.battle_report_inspect;
681.                 }
682.                 _ => {}
683.             }
684.             return;
685.         }
686. 
687.         if self.state.overlay.show_dispatch {
688.             match key.code {
689.                 KeyCode::Esc | KeyCode::Char('N') | KeyCode::Char('n') => {
690.                     self.state.overlay.show_dispatch = false;
691.                 }
692.                 KeyCode::Left | KeyCode::Char('h')
693.                     if self.state.overlay.dispatch_history_index > 0 =>
