1. //! Update checking, downloading, and staging for FARSPACE.
2. //!
3. //! This module is the only place in the workspace that performs network I/O.
4. //! All HTTP work runs on detached threads so the TUI is never blocked.
5. 
6. use game_tui::{UpdateChannel, UpdateInfo};
7. use serde::Deserialize;
8. use std::path::PathBuf;
9. use std::sync::mpsc;
10. use std::thread;
11. 
12. type UpdateCheckRx = mpsc::Receiver<Result<Option<UpdateInfo>, String>>;
13. type DownloadTx = mpsc::SyncSender<UpdateInfo>;
14. type DownloadResultRx = mpsc::Receiver<Result<String, String>>;
15. 
16. const GITHUB_API: &str = "https://api.github.com/repos/lgulliver/farspace/releases";
17. const CURRENT_VERSION: &str = env!("CARGO_PKG_VERSION");
18. 
19. // ---------------------------------------------------------------------------
20. // GitHub API response types
21. // ---------------------------------------------------------------------------
22. 
23. #[derive(Debug, Deserialize)]
24. struct GhRelease {
25.     tag_name: String,
26.     prerelease: bool,
27.     draft: bool,
28.     assets: Vec<GhAsset>,
29. }
30. 
31. #[derive(Debug, Deserialize)]
32. struct GhAsset {
33.     name: String,
34.     browser_download_url: String,
35. }
36. 
37. // ---------------------------------------------------------------------------
38. // Platform asset name
39. // ---------------------------------------------------------------------------
40. 
41. fn platform_asset_name() -> &'static str {
42.     #[cfg(all(target_os = "linux", target_arch = "x86_64"))]
43.     return "farspace-linux-x86_64";
44.     #[cfg(all(target_os = "linux", target_arch = "aarch64"))]
45.     return "farspace-linux-aarch64";
46.     #[cfg(all(target_os = "macos", target_arch = "x86_64"))]
47.     return "farspace-macos-x86_64";
48.     #[cfg(all(target_os = "macos", target_arch = "aarch64"))]
49.     return "farspace-macos-aarch64";
50.     #[cfg(all(target_os = "windows", target_arch = "x86_64"))]
51.     return "farspace-windows-x86_64.exe";
52.     #[cfg(not(any(
53.         all(target_os = "linux", target_arch = "x86_64"),
54.         all(target_os = "linux", target_arch = "aarch64"),
55.         all(target_os = "macos", target_arch = "x86_64"),
56.         all(target_os = "macos", target_arch = "aarch64"),
57.         all(target_os = "windows", target_arch = "x86_64"),
58.     )))]
59.     return "";
60. }
61. 
62. // ---------------------------------------------------------------------------
63. // Version comparison
64. // ---------------------------------------------------------------------------
65. 
66. /// Returns true if `candidate` is newer than the currently running binary.
67. ///
68. /// For stable/preview: compares semver strings (strips leading 'v').
69. /// For nightly: compares the date+time suffix lexicographically.
70. fn is_newer(channel: UpdateChannel, candidate: &str) -> bool {
71.     is_newer_against(
72.         channel,
73.         candidate,
74.         CURRENT_VERSION,
75.         option_env!("FARSPACE_BUILD_TAG").unwrap_or(""),
76.     )
77. }
78. 
79. /// Testable inner implementation of [`is_newer`] with explicit `current_version`
80. /// and `build_tag` parameters.
81. fn is_newer_against(
82.     channel: UpdateChannel,
83.     candidate: &str,
84.     current_version: &str,
85.     build_tag: &str,
86. ) -> bool {
87.     let candidate = candidate.trim_start_matches('v');
88.     match channel {
89.         UpdateChannel::Nightly => {
90.             // Tags: nightly-YYYYMMDD-HHMM  →  compare as strings (ISO order)
91.             if build_tag.is_empty() {
92.                 return false; // stable binary, ignore nightly updates
93.             }
94.             candidate > build_tag.trim_start_matches('v')
95.         }
96.         UpdateChannel::Stable | UpdateChannel::Preview => {
97.             // Simple lexicographic semver — good enough for MAJOR.MINOR.PATCH
98.             let current = current_version.trim_start_matches('v');
99.             semver_gt(candidate, current)
100.         }
101.     }
102. }
103. 
104. /// Semver greater-than that also considers prerelease suffixes.
105. ///
106. /// Numeric components (MAJOR.MINOR.PATCH) are compared first. When they are
107. /// equal the prerelease suffix (the part after the first '-') is compared
108. /// lexicographically so that, e.g., `0.2.0-alpha.2 > 0.2.0-alpha.1`.
109. fn semver_gt(a: &str, b: &str) -> bool {
110.     fn parse_nums(s: &str) -> [u64; 3] {
111.         let ver = s.split_once('-').map_or(s, |(v, _)| v);
112.         let mut parts = ver.split('.');
113.         [
114.             parts.next().and_then(|x| x.parse().ok()).unwrap_or(0),
115.             parts.next().and_then(|x| x.parse().ok()).unwrap_or(0),
116.             parts.next().and_then(|x| x.parse().ok()).unwrap_or(0),
117.         ]
118.     }
119.     fn parse_pre(s: &str) -> &str {
120.         s.split_once('-').map_or("", |(_, p)| p)
121.     }
122.     let (na, nb) = (parse_nums(a), parse_nums(b));
123.     if na != nb {
124.         na > nb
125.     } else {
126.         // Same numeric version: compare prerelease suffix lexicographically.
127.         parse_pre(a) > parse_pre(b)
128.     }
129. }
130. 
131. fn release_matches_channel(release: &GhRelease, channel: UpdateChannel) -> bool {
132.     if release.draft {
133.         return false;
134.     }
135.     match channel {
136.         UpdateChannel::Stable => !release.prerelease,
137.         UpdateChannel::Preview => {
138.             release.prerelease
139.                 && (release.tag_name.contains("alpha") || release.tag_name.contains("beta"))
140.         }
141.         UpdateChannel::Nightly => release.prerelease && release.tag_name.starts_with("nightly-"),
142.     }
143. }
144. 
145. // ---------------------------------------------------------------------------
146. // Public API
147. // ---------------------------------------------------------------------------
148. 
149. /// Set up the three channels for update checking and downloading.
150. ///
151. /// Returns `(check_rx, download_tx, download_rx)` to pass to
152. /// `App::set_update_channels()`.
153. pub fn setup_update_system(
154.     channel: UpdateChannel,
155. ) -> (UpdateCheckRx, DownloadTx, DownloadResultRx) {
156.     let (check_tx, check_rx) = mpsc::channel::<Result<Option<UpdateInfo>, String>>();
157.     let (request_tx, request_rx) = mpsc::sync_channel::<UpdateInfo>(1);
158.     let (result_tx, result_rx) = mpsc::channel::<Result<String, String>>();
159. 
160.     // Background update check
161.     thread::spawn(move || {
162.         let result = check_latest(channel).map_err(|e| e.to_string());
163.         let _ = check_tx.send(result);
164.     });
165. 
166.     // Background download worker
167.     thread::spawn(move || {
168.         while let Ok(info) = request_rx.recv() {
169.             let outcome = download_and_stage(&info)
170.                 .map(|_| info.version.clone())
171.                 .map_err(|e| e.to_string());
172.             if result_tx.send(outcome).is_err() {
173.                 break;
174.             }
175.         }
176.     });
177. 
178.     (check_rx, request_tx, result_rx)
179. }
180. 
181. /// Check GitHub releases for a newer version on the given channel.
182. /// Returns `Ok(Some(UpdateInfo))` if an update is available, `Ok(None)` if up-to-date,
183. /// or `Err` with a human-readable message if the check could not be completed.
184. fn check_latest(channel: UpdateChannel) -> anyhow::Result<Option<UpdateInfo>> {
185.     let asset_name = platform_asset_name();
186.     if asset_name.is_empty() {
187.         return Ok(None); // unsupported platform
188.     }
189. 
190.     let agent = ureq::AgentBuilder::new()
191.         .timeout_connect(std::time::Duration::from_secs(10))
192.         .timeout_read(std::time::Duration::from_secs(30))
193.         .build();
194. 
195.     let response: Vec<GhRelease> = agent
196.         .get(GITHUB_API)
197.         .set("User-Agent", &format!("farspace/{CURRENT_VERSION}"))
198.         .set("Accept", "application/vnd.github+json")
199.         .call()
200.         .map_err(|e| anyhow::anyhow!("update check request failed: {e}"))?
201.         .into_json()
202.         .map_err(|e| anyhow::anyhow!("update check response parse failed: {e}"))?;
203. 
204.     let release = match response
205.         .into_iter()
206.         .find(|r| release_matches_channel(r, channel))
207.     {
208.         Some(r) => r,
209.         None => return Ok(None),
210.     };
211. 
212.     if !is_newer(channel, &release.tag_name) {
213.         return Ok(None);
214.     }
215. 
216.     let asset = match release.assets.iter().find(|a| a.name == asset_name) {
217.         Some(a) => a,
218.         None => return Ok(None),
219.     };
220. 
221.     Ok(Some(UpdateInfo {
222.         version: release.tag_name.clone(),
223.         channel,
224.         download_url: asset.browser_download_url.clone(),
225.     }))
226. }
227. 
228. /// Download the update binary to a staging path next to the current executable.
229. /// The staged file has the current executable's extension replaced with `.update`
230. /// (e.g. `farspace` → `farspace.update`, `farspace.exe` → `farspace.update`).
231. /// It is applied on the next launch.
232. ///
233. /// NOTE: Downloads are protected by TLS only. A future improvement should
234. /// verify a signed manifest or SHA-256 checksum published alongside the release
235. /// asset before staging, to defend against compromised release metadata or a
236. /// network man-in-the-middle attack.
237. pub fn download_and_stage(info: &UpdateInfo) -> anyhow::Result<PathBuf> {
238.     let staging = staged_path()?;
239. 
240.     let agent = ureq::AgentBuilder::new()
241.         .timeout_connect(std::time::Duration::from_secs(10))
242.         .timeout_read(std::time::Duration::from_secs(300))
243.         .build();
244. 
245.     let response = agent
246.         .get(&info.download_url)
247.         .set("User-Agent", &format!("farspace/{CURRENT_VERSION}"))
248.         .call()?;
249. 
250.     let mut reader = response.into_reader();
251.     let mut file = std::fs::File::create(&staging)?;
252.     std::io::copy(&mut reader, &mut file)?;
253. 
254.     // Make executable on Unix
255.     #[cfg(unix)]
256.     {
257.         use std::os::unix::fs::PermissionsExt;
258.         let mut perms = std::fs::metadata(&staging)?.permissions();
259.         perms.set_mode(0o755);
260.         std::fs::set_permissions(&staging, perms)?;
261.     }
262. 
263.     Ok(staging)
264. }
265. 
266. /// Path where the staged update binary is written.
267. pub fn staged_path() -> anyhow::Result<PathBuf> {
268.     let mut path = std::env::current_exe()?;
269.     path.set_extension("update");
270.     Ok(path)
271. }
272. 
273. /// Check for a staged update and apply it before the TUI starts.
274. ///
275. /// On Unix: atomically renames the staged file over the current binary.
276. /// On Windows: copies the staged file over the current binary (best-effort).
277. ///
278. /// Returns `true` if an update was applied (the caller should note that the
279. /// binary on disk has changed, though the running process is the old version).
280. pub fn check_and_apply_staged() -> bool {
281.     let Ok(staged) = staged_path() else {
282.         return false;
283.     };
284.     if !staged.exists() {
285.         return false;
286.     }
287. 
288.     let Ok(current) = std::env::current_exe() else {
289.         let _ = std::fs::remove_file(&staged);
290.         return false;
291.     };
292. 
293.     let applied = apply_staged(&current, &staged);
294.     if applied {
295.         let _ = std::fs::remove_file(&staged);
296.     }
297.     applied
298. }
299. 
300. #[cfg(unix)]
301. fn apply_staged(current: &std::path::Path, staged: &std::path::Path) -> bool {
302.     std::fs::rename(staged, current).is_ok()
303. }
304. 
305. #[cfg(windows)]
306. fn apply_staged(current: &std::path::Path, staged: &std::path::Path) -> bool {
307.     std::fs::copy(staged, current).is_ok()
308. }
309. 
310. #[cfg(not(any(unix, windows)))]
311. fn apply_staged(_current: &std::path::Path, _staged: &std::path::Path) -> bool {
312.     false
313. }
