62. // ---------------------------------------------------------------------------
63. // Version comparison
64. // ---------------------------------------------------------------------------
65. 
66. /// Returns true if `candidate` is newer than the currently running binary.
67. ///
68. /// For stable/preview: compares semver strings (strips leading 'v').
69. /// For nightly: compares the date+time suffix lexicographically.
70. fn is_newer(channel: UpdateChannel, candidate: &str) -> bool {
71.     is_newer_against(
72.         channel,
73.         candidate,
74.         CURRENT_VERSION,
75.         option_env!("FARSPACE_BUILD_TAG").unwrap_or(""),
76.     )
77. }
78. 
79. /// Testable inner implementation of [`is_newer`] with explicit `current_version`
80. /// and `build_tag` parameters.
81. fn is_newer_against(
82.     channel: UpdateChannel,
83.     candidate: &str,
84.     current_version: &str,
85.     build_tag: &str,
86. ) -> bool {
87.     let candidate = candidate.trim_start_matches('v');
88.     match channel {
89.         UpdateChannel::Nightly => {
90.             // Tags: nightly-YYYYMMDD-HHMM  →  compare as strings (ISO order)
91.             if build_tag.is_empty() {
92.                 return false; // stable binary, ignore nightly updates
93.             }
94.             candidate > build_tag.trim_start_matches('v')
95.         }
96.         UpdateChannel::Stable | UpdateChannel::Preview => {
97.             // Simple lexicographic semver — good enough for MAJOR.MINOR.PATCH
98.             let current = current_version.trim_start_matches('v');
99.             semver_gt(candidate, current)
100.         }
101.     }
102. }
103. 
104. /// Semver greater-than that also considers prerelease suffixes.
105. ///
106. /// Numeric components (MAJOR.MINOR.PATCH) are compared first. When they are
107. /// equal the prerelease suffix (the part after the first '-') is compared
108. /// lexicographically so that, e.g., `0.2.0-alpha.2 > 0.2.0-alpha.1`.
109. fn semver_gt(a: &str, b: &str) -> bool {
110.     fn parse_nums(s: &str) -> [u64; 3] {
111.         let ver = s.split_once('-').map_or(s, |(v, _)| v);
112.         let mut parts = ver.split('.');
113.         [
114.             parts.next().and_then(|x| x.parse().ok()).unwrap_or(0),
115.             parts.next().and_then(|x| x.parse().ok()).unwrap_or(0),
116.             parts.next().and_then(|x| x.parse().ok()).unwrap_or(0),
117.         ]
118.     }
119.     fn parse_pre(s: &str) -> &str {
120.         s.split_once('-').map_or("", |(_, p)| p)
121.     }
122.     let (na, nb) = (parse_nums(a), parse_nums(b));
123.     if na != nb {
124.         na > nb
125.     } else {
126.         // Same numeric version: compare prerelease suffix lexicographically.
127.         parse_pre(a) > parse_pre(b)
128.     }
129. }
130. 
131. fn release_matches_channel(release: &GhRelease, channel: UpdateChannel) -> bool {
132.     if release.draft {
133.         return false;
134.     }
135.     match channel {
136.         UpdateChannel::Stable => !release.prerelease,
137.         UpdateChannel::Preview => {
138.             release.prerelease
139.                 && (release.tag_name.contains("alpha") || release.tag_name.contains("beta"))
140.         }
141.         UpdateChannel::Nightly => release.prerelease && release.tag_name.starts_with("nightly-"),
142.     }
143. }
