         Ok(Ok(())) => restore_result?,
         Ok(Err(e)) => {
             restore_result?;
             eprintln!("Application error: {}", e);
             std::process::exit(1);
         }
         Err(payload) => {
             let _ = restore_result;
             panic::resume_unwind(payload);
         }
     }

     Ok(())
 }

