542.         while !self.state.quit {
543.             self.poll_update_channels();
544. 
545.             terminal.draw(|frame| self.render(frame))?;
546.             self.state.tick_count = self.state.tick_count.wrapping_add(1);
547. 
548.             if event::poll(Duration::from_millis(100))? {
549.                 if let Event::Key(key) = event::read()? {
550.                     if key.kind == KeyEventKind::Press {
