1. //! New Game Setup screen — configure empire choice, galaxy seed, size, AI count, and other
2. //! scenario options before starting a new game. Empire selection happens on the EmpireSelect
3. //! screen; this screen shows the chosen empire as a read-only header.
4. 
5. use crate::app::AppState;
6. use crate::components::render_footer;
7. use crate::layout::compose_layout;
8. use crate::screens::Screen;
9. use crate::theme::Theme;
10. use game_core::{all_empire_definitions, GalaxySize, VictoryPath, VictorySettings};
11. use ratatui::{
12.     layout::{Alignment, Constraint, Direction, Layout, Rect},
13.     text::{Line, Span},
14.     widgets::{Block, Borders, Paragraph, Wrap},
15.     Frame,
16. };
17. 
18. /// Height of the setup box (border×2 + padding + rows)
19. const SETUP_BOX_HEIGHT: u16 = 32;
20. /// Minimum width of the setup box.
21. const SETUP_BOX_MIN_WIDTH: u16 = 72;
22. /// Maximum width of the setup box.
23. const SETUP_BOX_MAX_WIDTH: u16 = 112;
24. const FIELD_LABEL_WIDTH: usize = 14;
25. const FIELD_VALUE_WIDTH: usize = 20;
26. 
27. /// Index of each editable setup field in `AppState::setup_cursor`.
28. pub const FIELD_GALAXY_SIZE: usize = 0;
29. pub const FIELD_AI_COUNT: usize = 1;
30. pub const FIELD_SEED: usize = 2;
31. 
32. fn enter_hint(app_state: &AppState) -> &'static str {
33.     if app_state.new_game_setup.seed_editing {
34.         "Confirm Seed"
35.     } else {
36.         match app_state.new_game_setup.cursor {
37.             FIELD_SEED => "Edit Seed",
38.             _ => "Start",
39.         }
40.     }
41. }
42. 
43. fn setup_box_size(main_area: Rect) -> (u16, u16) {
44.     let width = main_area
45.         .width
46.         .min(SETUP_BOX_MAX_WIDTH)
47.         .max(SETUP_BOX_MIN_WIDTH.min(main_area.width));
48.     let height = main_area.height.min(SETUP_BOX_HEIGHT);
49.     (width, height)
50. }
51. 
52. fn pad_to_width(text: &str, width: usize) -> String {
53.     let len = text.chars().count();
54.     if len >= width {
55.         text.to_string()
56.     } else {
57.         format!("{text}{}", " ".repeat(width - len))
58.     }
59. }
60. 
61. fn field_line(label: &str, value: &str, is_active: bool, content_width: u16) -> Line<'static> {
62.     let marker = if is_active { ">" } else { " " };
63.     let text = format!(
64.         "{marker} {:<FIELD_LABEL_WIDTH$} {value:<FIELD_VALUE_WIDTH$}",
65.         label
66.     );
67.     if is_active {
68.         return Line::from(Span::styled(
69.             pad_to_width(&text, usize::from(content_width)),
70.             Theme::highlight_style(),
71.         ));
72.     }
73. 
74.     let prefix = format!("{marker} {label:<FIELD_LABEL_WIDTH$} ");
75.     let value_text = format!("{value:<FIELD_VALUE_WIDTH$}");
76.     let padding_width = usize::from(content_width)
77.         .saturating_sub(prefix.chars().count() + value_text.chars().count());
78. 
79.     Line::from(vec![
80.         Span::styled(prefix, Theme::default_style()),
81.         Span::styled(value_text, Theme::title_style()),
82.         Span::raw(" ".repeat(padding_width)),
83.     ])
84. }
85. 
86. fn selector_value(label: impl std::fmt::Display, has_prev: bool, has_next: bool) -> String {
87.     format!(
88.         "{}{}{}",
89.         if has_prev { "< " } else { "  " },
90.         label,
91.         if has_next { " >" } else { "  " }
92.     )
93. }
94. 
95. /// Render the new game setup screen.
96. pub fn render_new_game_setup(frame: &mut Frame, area: Rect, app_state: &AppState) {
97.     let (_header_area, main_area, footer_area) = compose_layout(area);
98.     render_footer(frame, footer_area, &Screen::NewGameSetup, None);
99. 
100.     let (setup_width, setup_height) = setup_box_size(main_area);
101. 
102.     // Center the setup box vertically and horizontally
103.     let v_chunks = Layout::default()
104.         .direction(Direction::Vertical)
105.         .constraints([
106.             Constraint::Fill(1),
107.             Constraint::Length(setup_height),
108.             Constraint::Fill(1),
109.         ])
110.         .split(main_area);
111. 
112.     let h_chunks = Layout::default()
113.         .direction(Direction::Horizontal)
114.         .constraints([
115.             Constraint::Fill(1),
116.             Constraint::Length(setup_width),
117.             Constraint::Fill(1),
118.         ])
119.         .split(v_chunks[1]);
120. 
121.     let box_area = h_chunks[1];
122.     let content_width = box_area.width.saturating_sub(2);
123. 
124.     let all_defs = all_empire_definitions();
125.     let empire_idx = app_state
126.         .new_game_setup
127.         .empire_cursor
128.         .min(all_defs.len().saturating_sub(1));
129.     let selected_def = &all_defs[empire_idx];
130. 
131.     // Derived summary values
132.     let star_count = app_state.new_game_setup.galaxy_size.default_star_count();
133.     let sector_count = app_state.new_game_setup.galaxy_size.default_sector_count();
134. 
135.     // Build content lines
136.     let mut lines: Vec<Line> = vec![Line::from("")];
137. 
138.     lines.push(Line::from(vec![Span::styled(
139.         "  GALAXY CONFIGURATION",
140.         Theme::title_style(),
141.     )]));
142.     lines.push(Line::from(""));
143. 
144.     // Empire header (read-only — chosen on the empire select screen)
145.     lines.push(Line::from(vec![
146.         Span::styled("  Playing as  ", Theme::muted_style()),
147.         Span::styled(
148.             format!("{} {}", selected_def.symbol, selected_def.name),
149.             Theme::title_style(),
150.         ),
151.     ]));
152.     lines.push(Line::from(vec![
153.         Span::raw("  "),
154.         Span::styled(selected_def.short_description, Theme::muted_style()),
155.     ]));
156.     lines.push(Line::from(""));
157. 
158.     // Galaxy Size field
159.     {
160.         let is_active = app_state.new_game_setup.cursor == FIELD_GALAXY_SIZE;
161.         let all_sizes = GalaxySize::all();
162.         let current_label = app_state.new_game_setup.galaxy_size.label();
163.         let idx = all_sizes
164.             .iter()
165.             .position(|s| *s == app_state.new_game_setup.galaxy_size)
166.             .unwrap_or(0);
167.         let has_prev = idx > 0;
168.         let has_next = idx + 1 < all_sizes.len();
169.         let value = selector_value(current_label, has_prev, has_next);
170.         lines.push(field_line("Galaxy Size", &value, is_active, content_width));
171.     }
172. 
173.     lines.push(Line::from(""));
174. 
175.     // AI Empire Count field
176.     {
177.         let is_active = app_state.new_game_setup.cursor == FIELD_AI_COUNT;
178.         let count = app_state.new_game_setup.ai_count;
179.         let value = selector_value(count, count > 1, count < 4);
180.         lines.push(field_line("AI Empires", &value, is_active, content_width));
181.     }
182. 
183.     lines.push(Line::from(""));
184. 
185.     // Seed field
186.     {
187.         let is_active = app_state.new_game_setup.cursor == FIELD_SEED;
188.         let seed_display = if app_state.new_game_setup.seed_editing {
189.             let mut s = app_state.new_game_setup.seed_str.clone();
190.             s.push('_'); // cursor indicator
191.             s
192.         } else {
193.             app_state.new_game_setup.seed_str.clone()
194.         };
195.         lines.push(field_line("Seed", &seed_display, is_active, content_width));
196.         if is_active && !app_state.new_game_setup.seed_editing {
197.             lines.push(Line::from(vec![Span::styled(
198.                 "  (press Enter to edit seed)",
199.                 Theme::muted_style(),
200.             )]));
201.         } else {
202.             lines.push(Line::from(""));
203.         }
204.     }
205. 
206.     lines.push(Line::from(""));
207. 
208.     // Derived summary
209.     lines.push(Line::from(vec![
210.         Span::styled("  Stars         ", Theme::muted_style()),
211.         Span::styled(star_count.to_string(), Theme::default_style()),
212.     ]));
213.     lines.push(Line::from(vec![
214.         Span::styled("  Sectors       ", Theme::muted_style()),
215.         Span::styled(sector_count.to_string(), Theme::default_style()),
216.     ]));
217.     lines.push(Line::from(vec![
218.         Span::styled("  Difficulty    ", Theme::muted_style()),
219.         Span::styled("Standard", Theme::muted_style()),
220.     ]));
221.     let defaults = VictorySettings::default_v1();
222.     let enabled = VictoryPath::tie_break_order()
223.         .iter()
224.         .filter(|path| defaults.is_enabled(**path))
225.         .map(|path| path.label())
226.         .collect::<Vec<_>>()
227.         .join(", ");
228.     let disabled = VictoryPath::tie_break_order()
229.         .iter()
230.         .filter(|path| !defaults.is_enabled(**path))
231.         .map(|path| path.label())
232.         .collect::<Vec<_>>()
233.         .join(", ");
234.     lines.push(Line::from(vec![
235.         Span::styled("  Victory On    ", Theme::muted_style()),
236.         Span::styled(enabled, Theme::default_style()),
237.     ]));
238.     lines.push(Line::from(vec![
239.         Span::styled("  Victory Off   ", Theme::muted_style()),
240.         Span::styled(disabled, Theme::muted_style()),
241.     ]));
242. 
243.     lines.push(Line::from(""));
244. 
245.     lines.push(Line::from(vec![
246.         Span::styled("  [S]", Theme::title_style()),
247.         Span::raw(" Start   "),
248.         Span::styled("  [Enter]", Theme::title_style()),
249.         Span::raw(format!(" {}   ", enter_hint(app_state))),
250.         Span::styled("[Esc]", Theme::title_style()),
251.         Span::raw(" Back"),
252.     ]));
253. 
254.     let paragraph = Paragraph::new(lines)
255.         .block(
256.             Block::default()
257.                 .borders(Borders::ALL)
258.                 .style(Theme::default_style()),
259.         )
260.         .alignment(Alignment::Left)
261.         .style(Theme::default_style())
262.         .wrap(Wrap { trim: false });
263. 
264.     frame.render_widget(paragraph, box_area);
265. }
