+const SETUP_BOX_MIN_WIDTH: u16 = 72;
+const SETUP_BOX_MAX_WIDTH: u16 = 120;
+const FIELD_LABEL_WIDTH: usize = 14;
+const FIELD_VALUE_WIDTH: usize = 18;
+const WIDE_LAYOUT_WIDTH: u16 = 118;
