+    let lines = vec![
+        field_line("Galaxy Size", &galaxy_value, is_size, inner.width),
+        Line::from(""),
+        field_line("AI Empires", &ai_value, is_ai, inner.width),
+        Line::from(""),
+        field_line("Seed", &seed_display, is_seed, inner.width),
