+fn enter_hint(app_state: &AppState) -> &'static str {
+    if app_state.new_game_setup.seed_editing {
+        "Confirm Seed"
+    } else if app_state.new_game_setup.cursor == FIELD_SEED {
+        "Edit Seed"
+    } else {
+        "Start"
+    }
+}
+
+fn setup_box_size(main_area: Rect) -> (u16, u16) {
+    let width = main_area
+        .width
+        .min(SETUP_BOX_MAX_WIDTH)
+        .max(SETUP_BOX_MIN_WIDTH.min(main_area.width));
+    let height = main_area.height.min(SETUP_BOX_HEIGHT);
+    (width, height)
+}
+
+fn pad_to_width(text: &str, width: usize) -> String {
+    let len = text.chars().count();
+    if len >= width {
+        text.to_string()
+    } else {
+        format!("{text}{}", " ".repeat(width - len))
+    }
+}
+
+fn centered_text(text: &str, width: usize) -> String {
+    let len = text.chars().count();
+    if len >= width {
+        text.to_string()
+    } else {
+        let left = (width - len) / 2;
+        let right = width - len - left;
+        format!("{}{}{}", " ".repeat(left), text, " ".repeat(right))
+    }
+}
+
+fn selector_value(label: impl std::fmt::Display, has_prev: bool, has_next: bool) -> String {
+    format!(
+        "{}{}{}",
+        if has_prev { "< " } else { "  " },
+        label,
+        if has_next { " >" } else { "  " }
+    )
+}
+
+fn field_line(label: &str, value: &str, is_active: bool, content_width: u16) -> Line<'static> {
+    let marker = if is_active { "▶" } else { " " };
+    let text = format!("{marker} {:<FIELD_LABEL_WIDTH$} {value:<FIELD_VALUE_WIDTH$}", label);
+    let padded = pad_to_width(&text, usize::from(content_width));
+    if is_active {
+        return Line::from(Span::styled(padded, Theme::highlight_style()));
+    }
+
+    let prefix = format!("{marker} {label:<FIELD_LABEL_WIDTH$} ");
+    let value_text = format!("{value:<FIELD_VALUE_WIDTH$}");
+    let padding_width = usize::from(content_width)
+        .saturating_sub(prefix.chars().count() + value_text.chars().count());
+
+    Line::from(vec![
+        Span::styled(prefix, Theme::default_style()),
+        Span::styled(value_text, Theme::title_style()),
+        Span::raw(" ".repeat(padding_width)),
+    ])
+}
+
+fn title_band_line(app_state: &AppState, title_width: usize) -> Line<'static> {
+    let left = Span::styled("FARSPACE", Theme::title_style());
+    let center = Span::styled("CHART • EXPAND • ENDURE", Theme::muted_style());
+    let right = Span::styled("New Campaign 2 / 5", Theme::muted_style());
+    let mut line = vec![left, Span::raw("  ".to_string())];
+    line.push(Span::raw(centered_text(" ", title_width.saturating_sub(4)).to_string()));
+    line.push(center);
+    line.push(Span::raw("  ".to_string()));
+    line.push(right);
+    if app_state.new_game_setup.seed_editing {
+        line.push(Span::raw("  "));
+        line.push(Span::styled("Seed editing", Theme::warning_style()));
+    }
+    Line::from(line)
+}
+
+fn stage_tracker_line() -> Line<'static> {
+    let current = CAMPAIGN_STAGE;
+    let stages = [
+        (1usize, "Empire"),
+        (2, "Galaxy"),
+        (3, "Rules"),
+        (4, "Summary"),
+        (5, "Launch"),
+    ];
+    let mut spans = Vec::new();
+    for (idx, label) in stages {
+        if !spans.is_empty() {
+            spans.push(Span::raw("   "));
+        }
+        let styled = if idx == current {
+            Style::default()
+                .fg(Theme::accent())
+                .add_modifier(Modifier::BOLD)
+        } else {
+            Theme::muted_style()
+        };
+        spans.push(Span::styled(format!("{idx} {label}"), styled));
+    }
+    Line::from(spans)
+}
