+    if area.width < COMPACT_MIN_WIDTH
+        || area.height < COMPACT_MIN_HEIGHT
+        || main_area.width < PREMIUM_MIN_WIDTH
+        || main_area.height < PREMIUM_MIN_HEIGHT
+    {
+        render_compact_new_game_setup(frame, main_area, app_state);
+        return;
+    }
