+    let (setup_width, setup_height) = setup_box_size(main_area);
+    let v_chunks = Layout::default()
+        .direction(Direction::Vertical)
+        .constraints([
+            Constraint::Fill(1),
+            Constraint::Length(setup_height),
+            Constraint::Fill(1),
+        ])
+        .split(main_area);
+    let h_chunks = Layout::default()
+        .direction(Direction::Horizontal)
+        .constraints([
+            Constraint::Fill(1),
+            Constraint::Length(setup_width),
+            Constraint::Fill(1),
+        ])
+        .split(v_chunks[1]);
+    let box_area = h_chunks[1];
+
+    let [title_area, content_area] = Layout::default()
+        .direction(Direction::Vertical)
+        .constraints([Constraint::Length(3), Constraint::Fill(1)])
+        .areas(box_area);
+    render_title_band(frame, title_area, app_state);
+
+    let wide = content_area.width >= WIDE_LAYOUT_WIDTH && content_area.height >= 18;
+    if wide {
+        let [left, right] = Layout::default()
+            .direction(Direction::Horizontal)
+            .constraints([Constraint::Percentage(40), Constraint::Percentage(60)])
+            .areas(content_area);
+        let [galaxy_area, preview_area] = Layout::default()
+            .direction(Direction::Vertical)
+            .constraints([Constraint::Length(11), Constraint::Fill(1)])
+            .areas(right);
+        render_empire_section(frame, left, app_state, false);
+        render_galaxy_section(frame, galaxy_area, app_state);
+        render_preview_section(frame, preview_area, app_state);
+    } else {
+        let [empire_area, galaxy_area, preview_area] = Layout::default()
+            .direction(Direction::Vertical)
+            .constraints([Constraint::Length(12), Constraint::Length(9), Constraint::Fill(1)])
+            .areas(content_area);
