1. //! New Game Setup screen — polished campaign wizard for choosing empire and scenario options.
2. 
3. use crate::app::AppState;
4. use crate::components::{
5.     render_empire_emblem, render_footer, EmblemPattern, EmpireEmblem, EmpireEmblemPalette,
6. };
7. use crate::layout::compose_layout;
8. use crate::screens::Screen;
9. use crate::theme::Theme;
10. use game_core::{all_empire_definitions, GalaxySize, VictoryPath, VictorySettings};
11. use ratatui::{
12.     layout::{Alignment, Constraint, Direction, Layout, Rect},
13.     style::{Color, Modifier, Style},
14.     text::{Line, Span},
15.     widgets::{Block, BorderType, Borders, Paragraph, Wrap},
16.     Frame,
17. };
18. 
19. /// Index of each editable setup field in `AppState::setup_cursor`.
20. pub const FIELD_GALAXY_SIZE: usize = 0;
21. pub const FIELD_AI_COUNT: usize = 1;
22. pub const FIELD_SEED: usize = 2;
23. 
24. const COMPACT_MIN_WIDTH: u16 = 80;
25. const COMPACT_MIN_HEIGHT: u16 = 24;
26. const PREMIUM_MIN_WIDTH: u16 = 96;
27. const PREMIUM_MIN_HEIGHT: u16 = 30;
28. const SETUP_BOX_HEIGHT: u16 = 28;
29. const SETUP_BOX_MIN_WIDTH: u16 = 72;
30. const SETUP_BOX_MAX_WIDTH: u16 = 120;
31. const FIELD_LABEL_WIDTH: usize = 14;
32. const FIELD_VALUE_WIDTH: usize = 18;
33. const WIDE_LAYOUT_WIDTH: u16 = 118;
34. const CAMPAIGN_STAGE: usize = 2;
35. 
36. fn enter_hint(app_state: &AppState) -> &'static str {
37.     if app_state.new_game_setup.seed_editing {
38.         "Confirm Seed"
39.     } else if app_state.new_game_setup.cursor == FIELD_SEED {
40.         "Edit Seed"
41.     } else {
42.         "Start"
43.     }
44. }
45. 
46. fn setup_box_size(main_area: Rect) -> (u16, u16) {
47.     let width = main_area
48.         .width
49.         .min(SETUP_BOX_MAX_WIDTH)
50.         .max(SETUP_BOX_MIN_WIDTH.min(main_area.width));
51.     let height = main_area.height.min(SETUP_BOX_HEIGHT);
52.     (width, height)
53. }
54. 
55. fn pad_to_width(text: &str, width: usize) -> String {
56.     let len = text.chars().count();
57.     if len >= width {
58.         text.to_string()
59.     } else {
60.         format!("{text}{}", " ".repeat(width - len))
61.     }
62. }
63. 
64. fn selector_value(label: impl std::fmt::Display, has_prev: bool, has_next: bool) -> String {
65.     format!(
66.         "{}{}{}",
67.         if has_prev { "< " } else { "  " },
68.         label,
69.         if has_next { " >" } else { "  " }
70.     )
