128. fn center_pad(text: &str, width: usize) -> String {
129.     let len = text.chars().count();
130.     if len >= width {
131.         let start = (len - width) / 2;
132.         return text.chars().skip(start).take(width).collect();
133.     }
134.     let left = (width - len) / 2;
135.     let right = width - len - left;
136.     format!("{}{}{}", " ".repeat(left), text, " ".repeat(right))
137. }
138. 
139. fn style_for_row(row: usize, total: usize, emblem: &EmpireEmblem) -> Style {
140.     if row == total / 2 {
141.         Style::default()
142.             .fg(emblem.palette.accent)
143.             .add_modifier(Modifier::BOLD)
144.     } else if row == 0 || row + 1 == total {
145.         Style::default().fg(emblem.palette.secondary)
146.     } else {
147.         Style::default()
148.             .fg(emblem.palette.primary)
149.             .add_modifier(Modifier::BOLD)
150.     }
151. }
152. 
153. fn fit_art(pattern: EmblemPattern, width: usize, height: usize) -> Vec<String> {
154.     let art = pattern.art();
155.     let base_height = art.len();
156.     let base_width = art.iter().map(|row| row.chars().count()).max().unwrap_or(0);
157.     let target_width = width.max(base_width);
158.     let target_height = height.max(base_height);
159. 
160.     let vertical_pad = target_height.saturating_sub(base_height) / 2;
161.     let mut lines = Vec::new();
162.     lines.extend(std::iter::repeat_with(String::new).take(vertical_pad));
163.     for row in art {
164.         lines.push(center_pad(row, target_width));
165.     }
166.     while lines.len() < target_height {
167.         lines.push(String::new());
168.     }
169.     lines
170. }
