172. /// Render an empire emblem into the target area.
173. pub fn render_empire_emblem(frame: &mut Frame, area: Rect, emblem: &EmpireEmblem) {
174.     if area.width == 0 || area.height == 0 {
175.         return;
176.     }
177. 
178.     let show_border = area.width >= 10 && area.height >= 7;
179.     let render_area = if show_border {
180.         let block = Block::default()
181.             .borders(Borders::ALL)
182.             .border_type(BorderType::Rounded)
183.             .border_style(Style::default().fg(emblem.palette.primary))
184.             .style(Style::default().bg(Theme::space_bg()));
185.         let inner = block.inner(area);
186.         frame.render_widget(block, area);
187.         inner
188.     } else {
189.         area
190.     };
191. 
192.     if render_area.width == 0 || render_area.height == 0 {
193.         return;
194.     }
195. 
196.     let target_height = if render_area.width >= 16 && render_area.height >= 9 {
197.         9
198.     } else if render_area.width >= 12 && render_area.height >= 7 {
199.         7
200.     } else {
201.         5
202.     } as usize;
203.     let target_width = if render_area.width >= 16 {
204.         9
205.     } else if render_area.width >= 12 {
206.         7
207.     } else {
208.         5
209.     } as usize;
210. 
211.     let art = fit_art(emblem.pattern, target_width, target_height);
212.     let top_pad = render_area.height.saturating_sub(art.len() as u16) / 2;
213.     let art_height = art.len() as u16;
214.     let used_rows = top_pad + art_height;
215.     let symbol_row = if render_area.height > used_rows { Some(used_rows) } else { None };
216. 
217.     let mut lines = Vec::new();
218.     lines.extend(std::iter::repeat_with(|| Line::from("")).take(top_pad as usize));
219.     for (row_idx, row) in art.iter().enumerate() {
220.         let style = style_for_row(row_idx, art.len(), emblem);
221.         lines.push(Line::from(Span::styled(row.clone(), style)));
222.     }
223.     if let Some(_) = symbol_row {
224.         lines.push(Line::from(Span::styled(
225.             format!("  {}", emblem.symbol),
226.             Style::default()
227.                 .fg(emblem.palette.accent)
228.                 .add_modifier(Modifier::BOLD),
229.         )));
230.     }
231. 
232.     frame.render_widget(
233.         Paragraph::new(lines)
234.             .alignment(Alignment::Center)
235.             .style(Theme::default_style()),
236.         render_area,
237.     );
238. }
239. 
240. /// Resolve an emblem for the given empire index.
241. pub fn resolve_empire_emblem(index: usize, symbol: char) -> EmpireEmblem {
242.     EmpireEmblem::from_empire_index(index, symbol)
243. }
244. 
