246. pub fn resolve_empire_emblem_for_definition(def: &EmpireDefinition) -> EmpireEmblem {
247.     let all_defs = all_empire_definitions();
248.     let index = all_defs
249.         .iter()
250.         .position(|candidate| candidate.id == def.id)
251.         .unwrap_or(def.id.0 as usize);
252.     resolve_empire_emblem(index, def.symbol)
253. }
