1. //! New Game Setup screen — polished campaign wizard for choosing empire and scenario options.
2. 
3. use crate::app::AppState;
4. use crate::components::{
5.     render_empire_emblem, render_footer, EmblemPattern, EmpireEmblem, EmpireEmblemPalette,
6. };
7. use crate::screens::Screen;
8. use crate::theme::Theme;
9. use game_core::{all_empire_definitions, GalaxySize, VictoryPath, VictorySettings};
10. use ratatui::{
11.     layout::{Alignment, Constraint, Direction, Layout, Rect},
12.     style::{Modifier, Style},
13.     text::{Line, Span},
14.     widgets::{Block, BorderType, Borders, Paragraph, Wrap},
15.     Frame,
16. };
17. 
18. /// Index of each editable setup field in `AppState::setup_cursor`.
19. pub const FIELD_GALAXY_SIZE: usize = 0;
20. pub const FIELD_AI_COUNT: usize = 1;
21. pub const FIELD_SEED: usize = 2;
22. 
23. const COMPACT_MIN_WIDTH: u16 = 80;
24. const COMPACT_MIN_HEIGHT: u16 = 24;
25. const PREMIUM_MIN_WIDTH: u16 = 96;
26. const PREMIUM_MIN_HEIGHT: u16 = 30;
27. const FIELD_LABEL_WIDTH: usize = 14;
28. const FIELD_VALUE_WIDTH: usize = 18;
29. const WIDE_LAYOUT_WIDTH: u16 = 118;
30. const CAMPAIGN_STAGE: usize = 2;
31. 
32. fn enter_hint(app_state: &AppState) -> &'static str {
33.     if app_state.new_game_setup.seed_editing {
34.         "Confirm Seed"
35.     } else if app_state.new_game_setup.cursor == FIELD_SEED {
36.         "Edit Seed"
37.     } else {
38.         "Start"
39.     }
40. }
41. 
42. fn pad_to_width(text: &str, width: usize) -> String {
43.     let len = text.chars().count();
44.     if len >= width {
45.         text.to_string()
46.     } else {
47.         format!("{text}{}", " ".repeat(width - len))
48.     }
49. }
50. 
51. fn selector_value(label: impl std::fmt::Display, has_prev: bool, has_next: bool) -> String {
52.     format!(
53.         "{}{}{}",
54.         if has_prev { "< " } else { "  " },
55.         label,
56.         if has_next { " >" } else { "  " }
57.     )
58. }
59. 
60. fn field_line(label: &str, value: &str, is_active: bool, content_width: u16) -> Line<'static> {
61.     let marker = if is_active { "▶" } else { " " };
62.     let text = format!(
63.         "{marker} {:<FIELD_LABEL_WIDTH$} {value:<FIELD_VALUE_WIDTH$}",
64.         label
65.     );
66.     let padded = pad_to_width(&text, usize::from(content_width));
67.     if is_active {
68.         return Line::from(Span::styled(padded, Theme::highlight_style()));
69.     }
70. 
71.     let prefix = format!("{marker} {label:<FIELD_LABEL_WIDTH$} ");
72.     let value_text = format!("{value:<FIELD_VALUE_WIDTH$}");
73.     let padding_width = usize::from(content_width)
74.         .saturating_sub(prefix.chars().count() + value_text.chars().count());
75. 
76.     Line::from(vec![
77.         Span::styled(prefix, Theme::default_style()),
78.         Span::styled(value_text, Theme::title_style()),
79.         Span::raw(" ".repeat(padding_width)),
80.     ])
81. }
82. 
83. fn title_band_line(app_state: &AppState) -> Line<'static> {
84.     let mut line = vec![
85.         Span::styled("FARSPACE", Theme::title_style()),
86.         Span::raw("  "),
87.         Span::styled("CHART • EXPAND • ENDURE", Theme::muted_style()),
88.         Span::raw("  "),
89.         Span::styled("New Campaign 2 / 5", Theme::muted_style()),
90.     ];
91.     if app_state.new_game_setup.seed_editing {
92.         line.push(Span::raw("  "));
93.         line.push(Span::styled("Seed editing", Theme::warning_style()));
94.     }
95.     Line::from(line)
96. }
97. 
98. fn stage_tracker_line() -> Line<'static> {
99.     let current = CAMPAIGN_STAGE;
100.     let stages = [
101.         (1usize, "Empire"),
102.         (2, "Galaxy"),
103.         (3, "Rules"),
104.         (4, "Summary"),
105.         (5, "Launch"),
106.     ];
107.     let mut spans = Vec::new();
108.     for (idx, label) in stages {
109.         if !spans.is_empty() {
110.             spans.push(Span::raw("   "));
111.         }
112.         let styled = if idx == current {
113.             Style::default()
114.                 .fg(Theme::accent())
115.                 .add_modifier(Modifier::BOLD)
116.         } else {
117.             Theme::muted_style()
118.         };
119.         spans.push(Span::styled(format!("{idx} {label}"), styled));
120.     }
121.     Line::from(spans)
122. }
