 };

 /// Index of each editable setup field in `AppState::setup_cursor`.
 pub const FIELD_GALAXY_SIZE: usize = 0;
 pub const FIELD_AI_COUNT: usize = 1;
 pub const FIELD_SEED: usize = 2;

 const COMPACT_MIN_WIDTH: u16 = 80;
