61. fn selected_star<'a>(
62.     app_state: &AppState,
63.     game_state: &'a GameState,
64. ) -> Option<&'a game_core::Star> {
65.     app_state
66.         .navigation
67.         .selected_star
68.         .and_then(|id| game_state.stars.get(&id))
69. }
