71. fn planet_survey_state(
72.     game_state: &GameState,
73.     star_id: game_core::StarId,
74.     planet_index: usize,
75.     planet_surveyed: bool,
76. ) -> &'static str {
77.     if !game_state.explored_stars.contains(&star_id) {
78.         return "Unknown";
79.     }
80. 
81.     if game_state
82.         .survey_missions
83.         .values()
84.         .any(|mission| mission.star == star_id && mission.planet_index == planet_index)
85.     {
86.         "Surveying"
87.     } else if planet_surveyed {
88.         "Surveyed"
89.     } else {
