106. fn render_orbital_panel(
107.     frame: &mut Frame,
108.     area: Rect,
109.     app_state: &AppState,
110.     game_state: &GameState,
111. ) {
112.     let glyphs = glyphs_for_mode(app_state.visual_mode);
113.     let block = Block::default()
114.         .title(" System Orbits ")
115.         .borders(Borders::ALL)
116.         .border_style(Theme::focused_border_style());
117.     let inner = block.inner(area);
118.     frame.render_widget(block, area);
119. 
120.     let star = match selected_star(app_state, game_state) {
121.         Some(star) => star,
122.         None => {
123.             frame.render_widget(
124.                 Paragraph::new("No system selected").style(Theme::muted_style()),
125.                 inner,
126.             );
127.             return;
128.         }
129.     };
130. 
131.     let mut lines = vec![Line::from(vec![
132.         Span::styled(format!("{} ", glyphs.star), Theme::title_style()),
133.         Span::styled(star.name.as_str(), Theme::title_style()),
134.         Span::styled(
135.             format!(" [{}]", star.spectral_class.as_char()),
136.             Style::default().fg(Theme::star_color(star.spectral_class)),
137.         ),
138.     ])];
139.     lines.push(Line::from(""));
140. 
141.     let split_height = (inner.height / 2)
142.         .max(4)
143.         .min(inner.height.saturating_sub(2));
144.     let panel_chunks = Layout::default()
145.         .direction(Direction::Vertical)
146.         .constraints([Constraint::Length(split_height), Constraint::Min(1)])
147.         .split(inner);
148.     render_system_visual(frame, panel_chunks[0], app_state, star);
149. 
150.     let selected_planet = app_state
151.         .navigation
152.         .selected_planet_index
153.         .min(star.planets.len().saturating_sub(1));
154.     for (index, planet) in star.planets.iter().enumerate() {
155.         let selected = index == selected_planet;
156.         let prefix = if selected {
157.             glyphs.list_selected.to_string()
158.         } else {
159.             " ".to_string()
160.         };
161.         let survey_state = planet_survey_state(game_state, star.id, index, planet.surveyed);
162.         let surveyed_mark = match survey_state {
163.             "Surveyed" => "S",
164.             "Surveying" => "~",
165.             "Unsurveyed" => "?",
166.             _ => "!",
167.         };
168.         // Determine if this planet's colony is currently blockaded
169.         let blockade_mark = planet
170.             .colony
171.             .and_then(|cid| game_state.colony_blockade_state(cid))
172.             .map(|_| glyphs.blockade.to_string())
173.             .unwrap_or_default();
174.         let invasion_mark = planet
175.             .colony
176.             .and_then(|cid| game_state.colonies.get(&cid))
177.             .and_then(|colony| {
178.                 (colony.owner != game_state.player_empire
179.                     && game_state
180.                         .relationship_status(game_state.player_empire, colony.owner)
181.                         .is_hostile_or_war())
182.                 .then_some(" [I]")
183.             })
184.             .unwrap_or("");
185.         let colony_mark = if planet.colony.is_some() {
186.             glyphs.planet_colonized.to_string()
187.         } else {
188.             glyphs.planet_uncolonized.to_string()
189.         };
190.         let label: Cow<'_, str> = if survey_state == "Surveyed" {
191.             Cow::Borrowed(planet.name.as_str())
192.         } else {
193.             Cow::Owned(format!("Orbit {}", index + 1))
194.         };
195.         let is_blockaded = !blockade_mark.is_empty();
196.         let style = if selected {
197.             Theme::highlight_style()
198.         } else if is_blockaded {
199.             Theme::error_style()
200.         } else if survey_state == "Surveyed" {
201.             Theme::default_style()
202.         } else {
203.             Theme::muted_style()
204.         };
205.         let mut spans = vec![
206.             Span::raw(format!("{} ", prefix)),
207.             Span::styled(format!("{} ", colony_mark), style),
208.             Span::styled(format!("{} ", surveyed_mark), style),
209.             Span::styled(format!("{}{}", label, invasion_mark), style),
210.             Span::styled(format!(" — {}", survey_state), Theme::muted_style()),
211.         ];
212.         if is_blockaded {
213.             spans.push(Span::styled(
214.                 format!(" {}", blockade_mark),
215.                 Theme::error_style(),
216.             ));
217.         }
218.         lines.push(Line::from(spans));
219.     }
